import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span

class RoundSpansTests(unittest.TestCase):
    def test_label_after_rounding(self):
        spans = [parse_span("09:04-17:11")]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        spans = [parse_span("09:08-10:22")]
        self.assertEqual(
            round_spans(spans, 15), ["09:15-10:15 (1h 00m)"]
        )

    def test_several_spans(self):
        spans = [
            parse_span("08:58-12:01"),
            parse_span("13:00-17:00")
        ]
        self.assertEqual(
            round_spans(spans, 30),
            ["09:00-12:00 (3h 00m)", "13:00-17:00 (4h 00m)"]
        )

    def test_bad_steps_raise(self):
        spans = [parse_span("09:00-10:00")]
        for step in (0, -15, 7, 25, 90):
            with self.assertRaises(ValueError):
                round_spans(spans, step)

if __name__ == "__main__":
    unittest.main()
